<script setup>
import {ref,computed} from 'vue'
import {withBase} from 'vitepress'
import data from './experience.json'
const selectedYear=ref('전체'),selectedIndustry=ref('전체'),query=ref('')
const filtered=computed(()=>query.value.trim().toLocaleLowerCase('ko-KR'))
const matches=name=>!filtered.value||name.toLocaleLowerCase('ko-KR').includes(filtered.value)
const found=computed(()=>data.years.some(y=>(selectedYear.value==='전체'||selectedYear.value===y.year)&&y.entries.some(e=>matches(e.name))))
</script>
<template><div class="marketing experience-page"><section class="section-inner release-section experience-hero"><a class="back-link" :href="withBase('/about.html')">← 회사 소개</a><span class="consult-eyebrow">주요 수행 실적</span><h1 id="page-title">기업·공공기관의 프로젝트 관리,<br>교육과 컨설팅으로 지원해 왔습니다.</h1><p>{{data.intro}}</p><nav class="experience-jumps" aria-label="실적 보기"><a href="#representative-cases">대표 수행 사례</a><a href="#industry-experience">산업별 실적</a><a href="#annual-experience">연도별 실적</a></nav></section>
<ExperienceProof full />
<section id="representative-cases" class="section-inner release-section"><div class="release-heading"><span class="consult-eyebrow">대표 수행 사례</span><h2>고객 과제와 수행 내용,<br>제공한 산출물을 확인하십시오.</h2></div><article v-for="c in data.cases" :key="c.id" :id="c.id" class="experience-case"><div><span class="consult-eyebrow">{{c.client}}</span><h3>{{c.title}}</h3></div><div><h4>고객 과제</h4><p>{{c.task}}</p><h4>수행 내용</h4><p>{{c.work}}</p><h4>산출물</h4><ul><li v-for="o in c.outputs" :key="o">{{o}}</li></ul><a class="text-link" :href="withBase('/consulting/pm.html')">프로젝트 관리 컨설팅 안내 ↗</a></div></article></section>
<section id="industry-experience" class="industry-experience"><div class="section-inner release-section"><div class="release-heading"><h2>산업별 주요 실적</h2><p>여러 산업에 걸친 교육·컨설팅 고객을 분야별로 확인하십시오.</p></div><label class="experience-filter">분야 선택<select v-model="selectedIndustry"><option>전체</option><option v-for="g in data.industry" :key="g.name">{{g.name}}</option></select></label><article v-for="g in data.industry" v-show="selectedIndustry==='전체'||selectedIndustry===g.name" :key="g.name" class="industry-group"><h3>{{g.name}}</h3><ul class="industry-names"><li v-for="name in g.names" :key="name">{{name}}</li></ul></article></div></section>
<section id="annual-experience" class="section-inner release-section"><div class="release-heading"><h2>연도별 주요 실적</h2><p>최근 실적부터 과거 수행 이력까지 확인하십시오.<br>동일 고객의 다른 연도 수행 이력은 각각 표시합니다.</p></div><div class="experience-filters"><label class="experience-filter">연도 선택<select v-model="selectedYear"><option>전체</option><option v-for="y in data.years" :key="y.year">{{y.year}}</option></select></label><label class="experience-filter">고객명 검색<input v-model="query" type="search" placeholder="예: 한국철도공사, 삼성전자"></label></div><p v-if="!found" role="status">조건에 맞는 실적이 없습니다. 연도나 검색어를 변경하십시오.</p><article v-for="y in data.years" v-show="(selectedYear==='전체'||selectedYear===y.year)&&y.entries.some(e=>matches(e.name))" :key="y.year" class="annual-group"><h3>{{y.year}}<span>년</span></h3><ul><li v-for="(e,i) in y.entries" v-show="matches(e.name)" :key="i">{{e.name}}</li></ul></article></section>
<InquiryPanel /><footer class="marketing-footer section-inner"><a :href="withBase('/')">PMOffice 피엠오피스</a><a :href="withBase('/about.html')">컨설팅</a><a :href="withBase('/ms-project/')">MS Project 교육</a><a :href="withBase('/ai-edu/')">AI 교육</a></footer></div></template>
